 {date:'Juin 2023 — Oct. 2025',company:'AR Compétences',role:'Développeuse 3D',type:'Stage puis alternance',text:'De la modélisation à la mise en mouvement, des créations 3D pensées pour le web et la communication.',items:['Modélisation sous Blender : iPhone 11 et trottinettes DUALTRON.','Animations web à 360° et vues éclatées.','Tracking vidéo pour l’animation de personnages.','Animation publicitaire, supports graphiques 2D et contribution aux publications Instagram et LinkedIn.'],tools:['Blender','Animation 3D','Création 2D']},
 {date:'Déc. 2022 — Fév. 2023',company:'Meimoun Cavendish',role:'Développeuse web',type:'Expérience professionnelle',text:'Faire évoluer l’identité et la présentation d’un site web.',items:['Actualisation des contenus et du visuel du site.','Création d’un logo et d’une carte de visite.'],tools:['Web','Identité visuelle']},
 {date:'Oct. 2021 — Juil. 2022',company:'Pardess',role:'Apprentie développeuse',type:'Apprentissage',text:'Entre maintenance web et conception d’une application mobile.',items:['Maintenance visuelle et éditoriale du site.','Projet d’application React Native : cahier des charges et créations sur Figma.'],tools:['React Native','Figma','Web']},
 {date:'Mai — Juin 2021',company:'NOLAM Embedded Systems',role:'Développeuse stagiaire',type:'Stage',text:'Une première expérience à la rencontre des interfaces et des systèmes embarqués.',items:['Initiation à JavaFX, Arduino et aux interfaces homme-machine.','Réception, décryptage et transmission de données.','Travail autour des bus CAN et SPI, avec Scene Builder et Eclipse.'],tools:['JavaFX','Arduino','CAN / SPI']}
