const formations=[['2023 — 2025','Master Réalité virtuelle et jeux vidéo','ESGI'],['2022 — 2023','Bachelor Réalité virtuelle et jeux vidéo','ESGI'],['2020 — 2022','BTS SIO · option SLAM','ORT Montreuil · Solutions logicielles et applications métiers'],['2019','Baccalauréat scientifique','']];
const skills=[['Création 3D','Blender · 3ds Max · Rhino3D'],['Temps réel','Unity (shaders & VFX) · Unreal Engine (Blueprints)'],['Développement','C++ · C# · Python · Rust · Java · JavaScript · PHP · SQL · OpenGL'],['Web & mobile','HTML/CSS · Symfony · React Native'],['Design','Figma · Illustrator · Photoshop'],['Langue & certifications','Anglais intermédiaire · ANSSI, Cisco et RGPD (2021)']];

export function setupJourney(){
 const dialog=document.createElement('dialog');dialog.id='journey-dialog';dialog.setAttribute('aria-labelledby','journey-title');
 dialog.innerHTML=`<header class="journey-header"><div><p class="eyebrow">LA MAISON · MON PARCOURS</p><h2 id="journey-title">Ruth Suliman<span>Développement & création 3D</span></h2></div><button class="close-modal" aria-label="Fermer mon parcours">×</button></header><p class="journey-intro">Formée en réalité virtuelle et jeux vidéo, mon parcours associe modélisation, animation et développement.</p><nav class="journey-tabs" aria-label="Rubriques de mon parcours"><button data-section="experience" class="active">Expériences</button><button data-section="education">Formations</button><button data-section="skills">Compétences</button></nav><div class="journey-content"></div><footer class="journey-footer"><span>Le parcours derrière les projets.</span><div class="journey-pager"><button data-step="-1" aria-label="Expérience précédente">←</button><span class="journey-count"></span><button data-step="1" aria-label="Expérience suivante">→</button></div></footer>`;
 document.body.append(dialog);let section='experience',index=0;
 function render(){
  dialog.querySelectorAll('[data-section]').forEach(b=>{b.classList.toggle('active',b.dataset.section===section);b.setAttribute('aria-pressed',String(b.dataset.section===section))});
  const host=dialog.querySelector('.journey-content');
  if(section==='experience'){const x=experience[index];host.innerHTML=`<article class="experience-card"><div class="experience-meta"><span class="journey-date">${x.date}</span><p>${x.type}</p><span class="experience-number">0${index+1}</span></div><div class="experience-copy"><h3>${x.role}</h3><h4>${x.company}</h4><p>${x.text}</p><ul>${x.items.map(t=>`<li>${t}</li>`).join('')}</ul><div class="journey-skills">${x.tools.map(t=>`<span>${t}</span>`).join('')}</div></div></article>`;}
  else if(section==='education')host.innerHTML=`<div class="education-list">${formations.map(x=>`<article><span class="journey-date">${x[0]}</span><div><h3>${x[1]}</h3><p>${x[2]}</p></div></article>`).join('')}</div>`;
  else host.innerHTML=`<div class="skill-list">${skills.map(x=>`<article><h3>${x[0]}</h3><p>${x[1]}</p></article>`).join('')}</div>`;
  dialog.querySelector('.journey-pager').hidden=section!=='experience';dialog.querySelector('.journey-count').textContent=`${index+1} / ${experience.length}`;dialog.querySelector('[data-step="-1"]').disabled=index===0;dialog.querySelector('[data-step="1"]').disabled=index===experience.length-1;
 }
 dialog.querySelector('.close-modal').onclick=()=>dialog.close();dialog.querySelectorAll('[data-section]').forEach(b=>b.onclick=()=>{section=b.dataset.section;render()});dialog.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>{index=Math.min(experience.length-1,Math.max(0,index+Number(b.dataset.step)));render()});
 dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
 return ()=>{render();if(!dialog.open)dialog.showModal()};
}
